<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {workspace} from '$lib/stores/workspace';import {infraState,infraCommand} from '$lib/infra/store';import {runtimeProfiles} from '$lib/infra/model.js';
 let project='',profile='',error='',notice='',lastProject='';
 $: available=$workspace.projects;$: {if(!project&&available.length)project=available[0].id;}
 $: {if(project!==lastProject){lastProject=project;profile=$infraState.runtimeAssignments[project]||'';}}
 function save(){try{infraCommand({type:'runtime-assign',project,profile});error='';notice='Runtime preference saved locally. No server runtime was installed or changed.';}catch(e){error=e instanceof Error?e.message:'Unable to save preference.';}}
</script>
<Heading title="Runtime profiles" subtitle="Recommended application environments and deployment defaults."/>
<div class="stack"><div class="callout"><strong>Runtime profiles are guidance only.</strong><p>Versions and processes on your VPS are not inspected here. Assigning a sample profile does not install packages, change the application build or restart a container.</p></div>
<section class="card"><h3>Available profiles</h3>{#each runtimeProfiles as p}<div class="setting-row"><div class="row"><span class="icon-box"><Icon name={p.id==='docker'?'Containers':p.id==='static'?'File':'Code'}/></span><div><strong>{p.name}</strong><small style="display:block">{p.for}</small></div></div><span class="muted">Suggested · port {p.port}</span></div>{/each}</section>
<section class="card stack"><div><h3>Project runtime preference</h3><p class="subtitle">Select a project and save its default runtime template.</p></div>{#if available.length}<form class="stack" on:submit|preventDefault={save}><div class="grid2"><label class="field">Project<select bind:value={project}>{#each available as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label class="field">Runtime profile<select bind:value={profile}><option value="">No preference</option>{#each runtimeProfiles as p}<option value={p.id}>{p.name}</option>{/each}</select></label></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<div><button type="submit" class="btn primary">Save preference</button></div></form>{:else}<p class="subtitle">Create a project first.</p><a href="/projects/new" class="btn secondary">Create project</a>{/if}</section></div>
